constraint.cypher:
MATCH (:Artifact)-[:CONTAINS]->(t:Class)
    WHERE NOT t:Test AND NOT t.name CONTAINS '$' AND NOT t.name IN ['package-info', 'module-info']
      AND NOT (:Type)-[:DEPENDS_ON]->(t)
      AND NOT EXISTS { MATCH (t)-[:ANNOTATED_BY]->(:Annotation)-[:OF_TYPE]->(at:Type) WHERE at.fqn STARTS WITH 'org.springframework.' OR at.fqn STARTS WITH 'jakarta.' OR at.fqn STARTS WITH 'javax.' }
      AND NOT EXISTS { MATCH (t)-[:DECLARES]->(m:Method {name: 'main'}) }
    RETURN DISTINCT t AS Element, t.fqn AS Fqn, 'no incoming dependency' AS Detail
